<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Products | Product Desk</title><link rel="stylesheet" href="<?= base_url('css/auth_layout.css'); ?>"></head>
<body><main><nav><div class="brand">Product Desk</div><div><span class="muted">Signed in as <?= htmlspecialchars($_SESSION['username'] ?? 'user', ENT_QUOTES, 'UTF-8'); ?></span><a href="<?= site_url('logout'); ?>">Sign out</a></div></nav><section class="panel"><div style="display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap"><div><h1>Products</h1><p class="muted">A simple catalog connected to your Aiven MySQL database.</p></div><a class="button" href="<?= site_url('products/create'); ?>">Add product</a></div><?php if (empty($products)): ?><p class="muted">No products yet. Add the first one to begin.</p><?php else: ?><table><thead><tr><th>Name</th><th>Description</th><th>Price</th><th>Quantity</th><th>Actions</th></tr></thead><tbody><?php foreach ($products as $product): ?><tr><td><?= htmlspecialchars($product['product_name'], ENT_QUOTES, 'UTF-8'); ?></td><td><?= nl2br(htmlspecialchars($product['description'] ?? '', ENT_QUOTES, 'UTF-8')); ?></td><td>$<?= number_format((float) $product['price'], 2); ?></td><td><?= (int) $product['quantity']; ?></td><td><div class="actions"><a class="button secondary" href="<?= site_url('products/edit/' . (int) $product['id']); ?>">Edit</a><form method="post" action="<?= site_url('products/delete/' . (int) $product['id']); ?>" onsubmit="return confirm('Delete this product?');"><button class="danger" type="submit">Delete</button></form></div></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></section></main></body></html>
